"""Generate engine/sim/src/sin_table.inc.

Q13 sine table, 512 entries per full turn plus a 128-entry quarter-turn tail so
cosine (index + 128) never wraps: value[i] = round(8192 * sin(2*pi*i/512)).
"""
import math
import pathlib

N, TAIL, ONE = 512, 128, 8192

values = [round(ONE * math.sin(2 * math.pi * i / N)) for i in range(N + TAIL)]
lines = [", ".join(f"{v}" for v in values[i:i + 16]) + "," for i in range(0, len(values), 16)]

out = pathlib.Path(__file__).resolve().parent.parent / "engine/sim/src/sin_table.inc"
out.write_text(
    "// Generated by tools/gen_sin_table.py - do not edit.\n"
    "// round(8192 * sin(2*pi*i/512)), i = 0..639\n"
    + "\n".join(lines) + "\n",
    newline="\n",
)
print(f"wrote {out} ({len(values)} entries)")
